using Xunit;

namespace ContosoUniversity.Tests
{
    public class PaginatedListTests
    {
        [Fact]
        public void Constructor_SetsPageIndex()
        {
            var items = new List<string> { "a", "b" };

            var result = new PaginatedList<string>(items, 10, 2, 5);

            Assert.Equal(2, result.PageIndex);
        }

        [Fact]
        public void Constructor_CalculatesTotalPages_RoundsUp()
        {
            var items = new List<string> { "a" };

            var result = new PaginatedList<string>(items, 11, 1, 5);

            Assert.Equal(3, result.TotalPages); // ceil(11/5) = 3
        }

        [Fact]
        public void Constructor_CalculatesTotalPages_ExactDivision()
        {
            var items = new List<string> { "a" };

            var result = new PaginatedList<string>(items, 10, 1, 5);

            Assert.Equal(2, result.TotalPages);
        }

        [Fact]
        public void Constructor_AddsItemsToList()
        {
            var items = new List<int> { 1, 2, 3 };

            var result = new PaginatedList<int>(items, 20, 1, 3);

            Assert.Equal(3, result.Count);
            Assert.Contains(1, result);
            Assert.Contains(2, result);
            Assert.Contains(3, result);
        }

        [Fact]
        public void HasPreviousPage_FirstPage_ReturnsFalse()
        {
            var result = new PaginatedList<int>(new List<int>(), 10, 1, 5);

            Assert.False(result.HasPreviousPage);
        }

        [Fact]
        public void HasPreviousPage_SecondPage_ReturnsTrue()
        {
            var result = new PaginatedList<int>(new List<int>(), 10, 2, 5);

            Assert.True(result.HasPreviousPage);
        }

        [Fact]
        public void HasNextPage_LastPage_ReturnsFalse()
        {
            var result = new PaginatedList<int>(new List<int>(), 10, 2, 5);

            Assert.False(result.HasNextPage); // TotalPages=2, PageIndex=2
        }

        [Fact]
        public void HasNextPage_NotLastPage_ReturnsTrue()
        {
            var result = new PaginatedList<int>(new List<int>(), 10, 1, 5);

            Assert.True(result.HasNextPage); // TotalPages=2, PageIndex=1
        }

        [Fact]
        public void Create_ReturnsCorrectPage()
        {
            var source = Enumerable.Range(1, 20).AsQueryable();

            var result = PaginatedList<int>.Create(source, 2, 5);

            Assert.Equal(2, result.PageIndex);
            Assert.Equal(4, result.TotalPages);
            Assert.Equal(5, result.Count);
            Assert.Equal(6, result[0]); // second page starts at item 6
            Assert.Equal(10, result[4]);
        }

        [Fact]
        public void Create_FirstPage_ReturnsFirstItems()
        {
            var source = Enumerable.Range(1, 10).AsQueryable();

            var result = PaginatedList<int>.Create(source, 1, 3);

            Assert.Equal(1, result.PageIndex);
            Assert.Equal(4, result.TotalPages); // ceil(10/3) = 4
            Assert.Equal(3, result.Count);
            Assert.Equal(1, result[0]);
            Assert.Equal(3, result[2]);
        }

        [Fact]
        public void Create_LastPage_ReturnsRemainingItems()
        {
            var source = Enumerable.Range(1, 10).AsQueryable();

            var result = PaginatedList<int>.Create(source, 4, 3);

            Assert.Single(result); // only 1 item on last page (10 items, page size 3, page 4)
            Assert.Equal(10, result[0]);
        }

        [Theory]
        [InlineData(1, 10, 1)]
        [InlineData(5, 10, 1)]
        [InlineData(10, 10, 1)]
        [InlineData(11, 10, 2)]
        [InlineData(100, 10, 10)]
        public void Constructor_TotalPages_CalculatedCorrectly(int count, int pageSize, int expectedTotalPages)
        {
            var result = new PaginatedList<int>(new List<int>(), count, 1, pageSize);

            Assert.Equal(expectedTotalPages, result.TotalPages);
        }
    }
}

using ContosoUniversity.Models;
using ContosoUniversity.Services;
using Xunit;

namespace ContosoUniversity.Tests.Services
{
    public class NotificationServiceTests : IDisposable
    {
        private readonly NotificationService _sut;

        public NotificationServiceTests()
        {
            _sut = new NotificationService();
            // Drain any existing notifications from static queue
            while (_sut.ReceiveNotification() != null) { }
        }

        public void Dispose()
        {
            _sut.Dispose();
        }

        [Fact]
        public void SendNotification_EnqueuesNotification_CanBeReceived()
        {
            _sut.SendNotification("Student", "1", EntityOperation.CREATE, "TestUser");

            var notification = _sut.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.Equal("Student", notification.EntityType);
            Assert.Equal("1", notification.EntityId);
            Assert.Equal("CREATE", notification.Operation);
            Assert.Equal("TestUser", notification.CreatedBy);
            Assert.False(notification.IsRead);
        }

        [Fact]
        public void SendNotification_WithDisplayName_GeneratesCorrectMessage()
        {
            _sut.SendNotification("Course", "101", "Math 101", EntityOperation.CREATE, "Admin");

            var notification = _sut.ReceiveNotification();

            Assert.Contains("Course 'Math 101'", notification.Message);
            Assert.Contains("created", notification.Message);
        }

        [Fact]
        public void SendNotification_WithoutDisplayName_UsesIdInMessage()
        {
            _sut.SendNotification("Student", "42", EntityOperation.UPDATE, "Admin");

            var notification = _sut.ReceiveNotification();

            Assert.Contains("Student (ID: 42)", notification.Message);
            Assert.Contains("updated", notification.Message);
        }

        [Fact]
        public void SendNotification_DeleteOperation_GeneratesDeleteMessage()
        {
            _sut.SendNotification("Department", "5", "Engineering", EntityOperation.DELETE, "Admin");

            var notification = _sut.ReceiveNotification();

            Assert.Contains("Department 'Engineering'", notification.Message);
            Assert.Contains("deleted", notification.Message);
        }

        [Fact]
        public void SendNotification_NullUserName_DefaultsToSystem()
        {
            _sut.SendNotification("Student", "1", EntityOperation.CREATE, null);

            var notification = _sut.ReceiveNotification();

            Assert.Equal("System", notification.CreatedBy);
        }

        [Fact]
        public void SendNotification_SetsCreatedAt()
        {
            var before = DateTime.Now;
            _sut.SendNotification("Student", "1", EntityOperation.CREATE);
            var after = DateTime.Now;

            var notification = _sut.ReceiveNotification();

            Assert.InRange(notification.CreatedAt, before, after);
        }

        [Fact]
        public void ReceiveNotification_EmptyQueue_ReturnsNull()
        {
            var result = _sut.ReceiveNotification();

            Assert.Null(result);
        }

        [Fact]
        public void ReceiveNotification_MultipleMessages_ReturnsFIFO()
        {
            _sut.SendNotification("Student", "1", EntityOperation.CREATE);
            _sut.SendNotification("Course", "2", EntityOperation.UPDATE);

            var first = _sut.ReceiveNotification();
            var second = _sut.ReceiveNotification();

            Assert.Equal("Student", first.EntityType);
            Assert.Equal("Course", second.EntityType);
        }

        [Fact]
        public void MarkAsRead_DoesNotThrow()
        {
            // MarkAsRead is a no-op for in-memory implementation
            var exception = Record.Exception(() => _sut.MarkAsRead(1));

            Assert.Null(exception);
        }

        [Fact]
        public void SendNotification_OverloadWithoutDisplayName_Works()
        {
            _sut.SendNotification("Instructor", "10", EntityOperation.UPDATE);

            var notification = _sut.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.Equal("Instructor", notification.EntityType);
            Assert.Equal("10", notification.EntityId);
        }

        [Theory]
        [InlineData(EntityOperation.CREATE, "created")]
        [InlineData(EntityOperation.UPDATE, "updated")]
        [InlineData(EntityOperation.DELETE, "deleted")]
        public void SendNotification_AllOperations_GenerateCorrectMessage(EntityOperation operation, string expectedVerb)
        {
            _sut.SendNotification("Entity", "1", "Test", operation);

            var notification = _sut.ReceiveNotification();

            Assert.Contains(expectedVerb, notification.Message);
        }
    }
}

